mapper.update:
UPDATE LIBRARY_CHECK SET library_check_number = #{library_check_number}, content = #{content},
org_file_name = #{org_file_name}, server_file_name = #{server_file_name}, file_extension = #{file_extension}, file_size = #{file_size},
modify_id = #{modify_id}, modify_date = SYSDATE WHERE library_check_idx = #{library_check_idx}

mapper.select:
${pagingTop}
SELECT
	b.library_check_idx, library_check_loan_idx, a.library_check_number, TO_CHAR(loan_start_date, 'yyyy-MM-dd') AS loan_start_date, TO_CHAR(loan_end_date, 'yyyy-MM-dd') AS loan_end_date,
	TO_CHAR(hope_date, 'yyyy-MM-dd') AS hope_date, b.hope_start_time, b.hope_start_minute, b.school_name, b.phone,
	b.school_tel, b.request_status, b.add_id, b.add_date, b.remark,
	(substr(b.request_name,1,1) || lpad('*',length(b.request_name)-2,'*') || substr(b.request_name, length(b.request_name), 1)) AS request_name
FROM
	LIBRARY_CHECK a, LIBRARY_CHECK_LOAN b
WHERE
	a.library_check_idx = b.library_check_idx

AND	${search_type} LIKE '%'||#{search_text}||'%'


AND	library_check_number = #{library_check_number}


AND	request_status = #{request_status}


AND	b.add_id = #{add_id}

ORDER BY b.add_date DESC
${pagingBottom}

SELECT
	COUNT(*)
FROM
	LIBRARY_CHECK a, LIBRARY_CHECK_LOAN b
WHERE
	a.library_check_idx = b.library_check_idx

AND	${search_type} LIKE '%'||#{search_text}||'%'


AND	library_check_number = #{library_check_number}


AND	request_status = #{request_status}


AND	b.add_id = #{add_id}

SELECT b.library_check_idx, b.library_check_loan_idx, a.library_check_number, TO_CHAR(b.loan_start_date, 'yyyy-MM-dd') AS loan_start_date, TO_CHAR(b.loan_end_date, 'yyyy-MM-dd') AS loan_end_date, TO_CHAR(b.hope_date, 'yyyy-MM-dd') AS hope_date, b.school_name, b.request_name, b.phone, b.school_tel, b.request_status, b.add_id, b.add_date, b.hope_start_time, b.hope_start_minute, b.remark FROM LIBRARY_CHECK a, LIBRARY_CHECK_LOAN b WHERE a.library_check_idx = b.library_check_idx
AND b.add_id = #{add_id}
ORDER BY b.add_date DESC

SELECT
	count(*)
FROM
	LIBRARY_CHECK a, LIBRARY_CHECK_LOAN b
WHERE
	a.library_check_idx = b.library_check_idx
AND	TO_CHAR(b.loan_start_date,'yyyy-MM-dd') <= #{loan_end_date}
AND TO_CHAR(b.loan_end_date,'yyyy-MM-dd') >= #{loan_start_date}
AND a.library_check_idx = #{library_check_idx}

SELECT
	TO_CHAR(TO_DATE(max(b.loan_end_date), 'yyyy-MM-dd') + 5, 'yyyy-MM-dd') as loan_end_date
FROM
	LIBRARY_CHECK a, LIBRARY_CHECK_LOAN b
WHERE
	a.library_check_idx = b.library_check_idx
AND	TO_CHAR(b.loan_start_date,'yyyy-MM-dd') <= #{loan_end_date}
AND TO_CHAR(b.loan_end_date,'yyyy-MM-dd') >= #{loan_start_date}
AND a.library_check_idx = #{library_check_idx}
